use std::collections::{HashMap, BinaryHeap};
use std::cmp::Reverse;

impl Solution {
    pub fn find_shortest_path(master: &GridMaster) -> i32 {
        let mut grid: HashMap<(i32, i32), i32> = HashMap::new();
        let mut target: (i32, i32) = (i32::MIN, i32::MIN);
        grid.insert((0, 0), 0);

        fn dfs(master: &GridMaster, r: i32, c: i32, grid: &mut HashMap<(i32, i32), i32>, target: &mut (i32, i32)) {
            if master.is_target() {
                *target = (r, c);
            }
            let dirs: &[(char, i32, i32, char)] = &[('U',-1,0,'D'),('D',1,0,'U'),('L',0,-1,'R'),('R',0,1,'L')];
            for &(d, dr, dc, back) in dirs {
                let (nr, nc) = (r + dr, c + dc);
                if master.can_move(d) && !grid.contains_key(&(nr, nc)) {
                    let cost = master.move_robot(d);
                    grid.insert((nr, nc), cost);
                    dfs(master, nr, nc, grid, target);
                    master.move_robot(back);
                }
            }
        }

        dfs(master, 0, 0, &mut grid, &mut target);

        if target == (i32::MIN, i32::MIN) { return -1; }

        let mut dist: HashMap<(i32, i32), i32> = HashMap::new();
        let mut heap: BinaryHeap<Reverse<(i32, i32, i32)>> = BinaryHeap::new();
        heap.push(Reverse((0, 0, 0)));

        while let Some(Reverse((cost, r, c))) = heap.pop() {
            if (r, c) == target { return cost; }
            if dist.get(&(r,c)).map_or(false, |&d| d <= cost) { continue; }
            dist.insert((r, c), cost);
            for (dr, dc) in [(-1i32,0i32),(1,0),(0,-1),(0,1)] {
                let (nr, nc) = (r+dr, c+dc);
                if let Some(&cc) = grid.get(&(nr,nc)) {
                    let nc2 = cost + cc;
                    if dist.get(&(nr,nc)).map_or(true, |&d| nc2 < d) {
                        heap.push(Reverse((nc2, nr, nc)));
                    }
                }
            }
        }
        -1
    }
}
```

## Problem Explanation

We need to find the total number of subarrays whose sum equals `k`.

### Key Insight: Prefix Sum + HashMap

The core idea is using **prefix sums**. 

- Let `prefix[i]` = sum of elements from index `0` to `i-1`
- A subarray from index `j` to `i` has sum = `prefix[i] - prefix[j]`
- We want: `prefix[i] - prefix[j] = k`
- Which means: `prefix[j] = prefix[i] - k`

So for each index `i`, we need to count how many previous prefix sums equal `prefix[i] - k`.

### Algorithm:
1. Use a HashMap to store the frequency of each prefix sum seen so far
2. Initialize with `{0: 1}` (empty subarray has sum 0)
3. For each element, update the running sum
4. Check if `(currentSum - k)` exists in the map - if yes, add its count to result
5. Update the map with the current sum

### Visual Example:
```
nums = [1, 1, 1], k = 2

prefixMap = {0: 1}
i=0: sum=1, look for (1-2)=-1 → not found, map={0:1, 1:1}
i=1: sum=2, look for (2-2)=0 → found! count+=1, map={0:1, 1:1, 2:1}
i=2: sum=3, look for (3-2)=1 → found! count+=1, map={0:1, 1:1, 2:1, 3:1}
Result = 2 ✓
```

## Code

```cpp
#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        // HashMap to store frequency of prefix sums
        unordered_map<int, int> prefixCount;

        // Initialize: empty subarray has sum 0 (occurs once)
        prefixCount[0] = 1;

        int currentSum = 0;
        int result = 0;

        for (int i = 0; i < nums.size(); i++) {
            // Update running prefix sum
            currentSum += nums[i];

            // Check if (currentSum - k) exists in map
            // If prefix[j] = currentSum - k exists, then subarray [j+1...i] has sum k
            int complement = currentSum - k;

            if (prefixCount.find(complement) != prefixCount.end()) {
                result += prefixCount[complement];
            }

            // Update the frequency of current prefix sum
            prefixCount[currentSum]++;
        }

        return result;
    }
};
```

## Complexity Analysis

| Complexity | Value | Reason |
|-----------|-------|--------|
| **Time** | O(n) | Single pass through array, HashMap operations are O(1) average |
| **Space** | O(n) | HashMap can store at most n+1 different prefix sums |

## Why Brute Force Doesn't Work Well

A brute force O(n²) approach would check all pairs (i, j) and calculate subarray sums, but with n up to 2×10⁴, this gives 4×10⁸ operations - too slow.

## Edge Cases Handled:
1. **Negative numbers**: Prefix sum approach works regardless of sign
2. **k = 0**: The `prefixCount[0] = 1` initialization handles subarrays that sum to 0
3. **Single element = k**: Works naturally with the algorithm
4. **Multiple subarrays with same sum**: HashMap frequency counting handles this

## Getting Column Data from Column Label String in wxGrid

Here's how to find a column by its label and get data from a specific row:

### Helper Function to Find Column Index by Label

```cpp
#include <wx/grid.h>

// Find column index by label string
int FindColumnByLabel(wxGrid* grid, const wxString& label)
{
    int numCols = grid->GetNumberCols();
    for (int col = 0; col < numCols; col++)
    {
        if (grid->GetColLabelValue(col) == label)
        {
            return col;  // Return column index
        }
    }
    return -1;  // Column not found
}
```

---

### Getting Cell Value from a Specific Row Using Column Label

```cpp
wxString GetCellValueByColumnLabel(wxGrid* grid, int row, const wxString& columnLabel)
{
    int col = FindColumnByLabel(grid, columnLabel);

    if (col == -1)
    {
        wxLogWarning("Column '%s' not found!", columnLabel);
        return wxEmptyString;
    }

    if (row < 0 || row >= grid->GetNumberRows())
    {
        wxLogWarning("Row %d is out of range!", row);
        return wxEmptyString;
    }

    return grid->GetCellValue(row, col);
}
```

