The core approach is:
1. **Iterate** through columns using `GetColLabelValue()`
2. **Match** the label string to find the column index
3. **Use** `GetCellValue(row, col)` with the found index to retrieve data

## Solution: Element Detection in Array

### Code

```javascript
/**
 * Detects if a given element exists in an array
 * Handles type mismatches and duplicate elements
 * @param {Array} arr - The array to search in
 * @param {*} searchElement - The element to search for
 * @returns {Object} - Result object with details
 */
function detectElement(arr, searchElement) {
  // Validate input
  if (!Array.isArray(arr)) {
    return { error: "First argument must be an array" };
  }

  // ── Strict search (no type coercion) ──────────────────────────────────────
  const strictIndices = arr.reduce((indices, element, index) => {
    if (element === searchElement) indices.push(index);
    return indices;
  }, []);

  // ── Loose search (with type coercion) ─────────────────────────────────────
  const looseIndices = arr.reduce((indices, element, index) => {
    if (element == searchElement) indices.push(index);  // == allows coercion
    return indices;
  }, []);

  // ── Build result ──────────────────────────────────────────────────────────
  const result = {
    array: arr,
    searchElement: searchElement,
    searchElementType: typeof searchElement,

    // Strict match (===)
    strictMatch: {
      found: strictIndices.length > 0,
      occurrences: strictIndices.length,
      indices: strictIndices,
    },

    // Loose match (==)
    looseMatch: {
      found: looseIndices.length > 0,
      occurrences: looseIndices.length,
      indices: looseIndices,
    },

    // Type information
    typeMismatch:
      looseIndices.length > 0 &&
      typeof arr[looseIndices[0]] !== typeof searchElement,
  };

  return result;
}

// ── Helper: Pretty print results ──────────────────────────────────────────────
function printResults(result) {
  if (result.error) {
    console.log(`Error: ${result.error}`);
    return;
  }

  console.log("═══════════════════════════════════════════");
  console.log(`Array          : [${result.array}]`);
  console.log(`Search Element : ${result.searchElement}`);
  console.log(`Element Type   : ${result.searchElementType}`);
  console.log("───────────────────────────────────────────");

  // Strict match
  console.log("\n🔍 Strict Search (===) — No Type Coercion:");
  console.log(`   Found       : ${result.strictMatch.found}`);
  console.log(`   Occurrences : ${result.strictMatch.occurrences}`);
  console.log(`   Indices     : [${result.strictMatch.indices}]`);

  // Loose match
  console.log("\n🔍 Loose Search (==) — With Type Coercion:");
  console.log(`   Found       : ${result.looseMatch.found}`);
  console.log(`   Occurrences : ${result.looseMatch.occurrences}`);
  console.log(`   Indices     : [${result.looseMatch.indices}]`);

  // Type mismatch warning
  if (result.typeMismatch) {
    console.log(
      "\n⚠️  Type Mismatch Detected! Element found only via type coercion."
    );
    console.log(
      `   Array element type : ${typeof result.array[result.looseMatch.indices[0]]}`
    );
    console.log(`   Search element type: ${result.searchElementType}`);
  }

  console.log("═══════════════════════════════════════════\n");
}

// ── Test Cases ────────────────────────────────────────────────────────────────
const array = [1, 2, 3, 4, 5, 5, 4, 3, 2, 1];

console.log("TEST 1: Search for string '3' in number array");
printResults(detectElement(array, "3"));

console.log("TEST 2: Search for number 3 in number array");
printResults(detectElement(array, 3));

console.log("TEST 3: Search for number 6 (not in array)");
printResults(detectElement(array, 6));

console.log("TEST 4: Search for boolean true");
printResults(detectElement(array, true));
```

### Output

```
TEST 1: Search for string '3' in number array
═══════════════════════════════════════════
Array          : [1,2,3,4,5,5,4,3,2,1]
Search Element : 3
Element Type   : string
───────────────────────────────────────────

🔍 Strict Search (===) — No Type Coercion:
   Found       : false       ← "3" !== 3
   Occurrences : 0
   Indices     : []

🔍 Loose Search (==) — With Type Coercion:
   Found       : true        ← "3" == 3
   Occurrences : 2
   Indices     : [2,7]

⚠️  Type Mismatch Detected! Element found only via type coercion.
   Array element type : number
   Search element type: string
═══════════════════════════════════════════

TEST 2: Search for number 3 in number array
...
   Strict → Found: true | Occurrences: 2 | Indices: [2, 7]

TEST 3: Search for number 6 (not in array)
...
   Strict → Found: false | Occurrences: 0
```

### Key Concepts

| Feature | Description |
|---|---|
| `===` Strict | Checks value **and** type — `"3" !== 3` |
| `==` Loose | Allows type coercion — `"3" == 3` |
| Type Mismatch | Detected when loose finds but strict doesn't |
| Duplicates | All indices are tracked, not just the first |

