package com.webapp.dao;

import com.webapp.model.User;
import com.webapp.util.DatabaseUtil;

import java.sql.*;

public class UserDAO {

    private static final String INSERT_USER_SQL =
        "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";

    private static final String CHECK_EMAIL_SQL =
        "SELECT COUNT(*) FROM users WHERE email = ?";

    /**
     * Registers a new user in the database
     * @param user - User object containing registration details
     * @return true if registration is successful, false otherwise
     */
    public boolean registerUser(User user) throws SQLException {
        Connection conn = null;
        PreparedStatement stmt = null;

        try {
            conn = DatabaseUtil.getConnection();
            stmt = conn.prepareStatement(INSERT_USER_SQL);

            stmt.setString(1, user.getName());
            stmt.setString(2, user.getEmail());
            stmt.setString(3, user.getPassword()); // Should be hashed (see notes)

            int rowsAffected = stmt.executeUpdate();
            return rowsAffected > 0;

        } finally {
            // Always close resources
            if (stmt != null) stmt.close();
            DatabaseUtil.closeConnection(conn);
        }
    }

    /**
     * Checks if an email address already exists in the database
     * @param email - Email to check
     * @return true if email exists, false otherwise
     */
    public boolean emailExists(String email) throws SQLException {
        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = DatabaseUtil.getConnection();
            stmt = conn.prepareStatement(CHECK_EMAIL_SQL);
            stmt.setString(1, email);

            rs = stmt.executeQuery();
            if (rs.next()) {
                return rs.getInt(1) > 0;
            }
            return false;

        } finally {
            if (rs != null) rs.close();
            if (stmt != null) stmt.close();
            DatabaseUtil.closeConnection(conn);
        }
    }
}
