```java
package com.webapp.servlet;

import com.webapp.dao.UserDAO;
import com.webapp.model.User;

import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.*;

import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

@WebServlet("/register")
public class RegisterServlet extends HttpServlet {

    private final UserDAO userDAO = new UserDAO();

    /**
     * Handles GET request - displays the registration form
     */
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        request.getRequestDispatcher("/register.html").forward(request, response);
    }

    /**
     * Handles POST request - processes registration form submission
     */
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // 1. Retrieve form parameters
        String name     = request.getParameter("name");
        String email    = request.getParameter("email");
        String password = request.getParameter("password");
        String confirmPassword = request.getParameter("confirmPassword");

        // 2. Validate input fields
        String errorMessage = validateInput(name, email, password, confirmPassword);
        if (errorMessage != null) {
            request.setAttribute("errorMessage", errorMessage);
            request.getRequestDispatcher("/register.html").forward(request, response);
            return;
        }

        try {
            // 3. Check if email already exists
            if (userDAO.emailExists(email)) {
                request.setAttribute("errorMessage", "Email address is already registered!");
                request.getRequestDispatcher("/register.html").forward(request, response);
                return;
            }

            // 4. Hash the password before storing
            String hashedPassword = hashPassword(password);

            // 5. Create and save the User object
            User user = new User(name.trim(), email.trim().toLowerCase(), hashedPassword);
            boolean isRegistered = userDAO.registerUser(user);

            if (isRegistered) {
                // 6. Set success message and redirect
                request.setAttribute("successMessage",
                    "Registration successful! Welcome, " + name + "!");
                request.getRequestDispatcher("/success.jsp").forward(request, response);
            } else {
                request.setAttribute("errorMessage", "Registration failed. Please try again.");
                request.getRequestDispatcher("/register.html").forward(request, response);
            }

        } catch (Exception e) {
            // Log the exception (use a proper logger in production)
            System.err.println("Registration error: " + e.getMessage());
            request.setAttribute("errorMessage", "A system error occurred. Please try again later.");
            request.getRequestDispatcher("/register.html").forward(request, response);
        }
    }

    /**
     * Validates registration form inputs
     * @return error message string, or null if valid
     */
    private String validateInput(String name, String email, String password, String confirmPassword) {
        // Check for empty fields
        if (name == null || name.trim().isEmpty()) {
            return "Name is required.";
        }
        if (email == null || email.trim().isEmpty()) {
            return "Email address is required.";
        }
        if (password == null || password.isEmpty()) {
            return "Password is required.";
        }
        if (confirmPassword == null || confirmPassword.isEmpty()) {
            return "Please confirm your password.";
        }

        // Validate name length
        if (name.trim().length() < 2 || name.trim().length() > 50) {
            return "Name must be between 2 and 50 characters.";
        }

        // Validate email format using regex
        if (!email.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$")) {
            return "Please enter a valid email address.";
        }

        // Validate password strength
        if (password.length() < 8) {
            return "Password must be at least 8 characters long.";
        }
        if (!password.matches(".*[A-Z].*")) {
            return "Password must contain at least one uppercase letter.";
        }
        if (!password.matches(".*[0-9].*")) {
            return "Password must contain at least one number.";
        }

        // Check if passwords match
        if (!password.equals(confirmPassword)) {
            return "Passwords do not match.";
        }

        return null; // All validations passed
    }

    /**
     * Hashes a password using SHA-256
     * NOTE: Use BCrypt in production for better security
     */
    private String hashPassword(String password) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hashedBytes = md.digest(password.getBytes());
            return Base64.getEncoder().encodeToString(hashedBytes);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Password hashing failed: " + e.getMessage());
        }
    }
}
