# Solution in Object Pascal

## Approach
For each query, we need to find a substring whose decimal value equals `first XOR second`. We can precompute all possible substrings and their values, storing the shortest one (with minimum left index) for each value.

Since the string length is up to 10^4, substrings can have values up to 2^10000, which is huge. However, `first` and `second` are at most 10^9 ≈ 2^30, so we only need substrings of length ≤ 30.

```pascal
program Solution;

uses
  SysUtils, Generics.Collections;

type
  TIntPair = record
    Left, Right: Integer;
  end;

  TValueMap = TDictionary<Int64, TIntPair>;

function SubstringsXorQueries(s: string; queries: array of array of Integer): TArray<TArray<Integer>>;
var
  n, i, j, length_: Integer;
  target: Int64;
  valueMap: TValueMap;
  val: Int64;
  pair: TIntPair;
  ans: TArray<TArray<Integer>>;
  maxLen: Integer;
begin
  n := Length(s);
  valueMap := TValueMap.Create;

  try
    // Precompute all substrings of length 1 to 30
    // (since first, second <= 10^9 < 2^30)
    maxLen := 30;
    if maxLen > n then
      maxLen := n;

    // We want shortest substring with minimum left index
    // Process from longer to shorter so shorter ones overwrite longer ones
    // Actually, process from shorter to longer won't work directly
    // Instead: for each starting position, compute values for increasing lengths
    // We want minimum length first, and for same length, minimum left index
    // Strategy: iterate length from 1 to maxLen, and for each length iterate all positions
    // Store in map only if not already present (first occurrence = minimum left for minimum length)

    for length_ := 1 to maxLen do
    begin
      for i := 1 to n - length_ + 1 do
      begin
        // Compute value of s[i..i+length_-1] (1-indexed in Pascal)
        val := 0;
        for j := i to i + length_ - 1 do
        begin
          val := val * 2 + (Ord(s[j]) - Ord('0'));
        end;

        if not valueMap.ContainsKey(val) then
        begin
          pair.Left := i - 1;  // Convert to 0-indexed
          pair.Right := i + length_ - 2;  // Convert to 0-indexed
          valueMap.Add(val, pair);
        end;
      end;
    end;

    // Answer queries
    SetLength(ans, Length(queries));
    for i := 0 to Length(queries) - 1 do
    begin
      target := queries[i][0] xor queries[i][1];
      SetLength(ans[i], 2);

      if valueMap.TryGetValue(target, pair) then
      begin
        ans[i][0] := pair.Left;
        ans[i][1] := pair.Right;
      end
      else
      begin
        ans[i][0] := -1;
        ans[i][1] := -1;
      end;
    end;

    Result := ans;
  finally
    valueMap.Free;
  end;
end;

// Optimized version with prefix computation
function SubstringsXorQueriesOptimized(s: string; queries: array of array of Integer): TArray<TArray<Integer>>;
var
  n, i, j, len: Integer;
  target: Int64;
  valueMap: TValueMap;
  val: Int64;
  pair: TIntPair;
  ans: TArray<TArray<Integer>>;
begin
  n := Length(s);
  valueMap := TValueMap.Create;

  try
    // For each starting position, compute values incrementally
    // Process by length to ensure shortest is stored first
    for len := 1 to Min(30, n) do
    begin
      for i := 1 to n - len + 1 do
      begin
        if len = 1 then
          val := Ord(s[i]) - Ord('0')
        else
        begin
          // Recompute (could optimize but n is small enough)
          val := 0;
          for j := i to i + len - 1 do
            val := val * 2 + (Ord(s[j]) - Ord('0'));
        end;

        if not valueMap.ContainsKey(val) then
        begin
          pair.Left := i - 1;
          pair.Right := i + len - 2;
          valueMap.Add(val, pair);
        end;
      end;
    end;

    SetLength(ans, Length(queries));
    for i := 0 to Length(queries) - 1 do
    begin
      target := Int64(queries[i][0]) xor Int64(queries[i][1]);
      SetLength(ans[i], 2);

      if valueMap.TryGetValue(target, pair) then
      begin
        ans[i][0] := pair.Left;
        ans[i][1] := pair.Right;
      end
      else
      begin
        ans[i][0] := -1;
        ans[i][1] := -1;
      end;
    end;

    Result := ans;
  finally
    valueMap.Free;
  end;
end;

begin
  // Test cases would go here
end.
```

## Key Points

1. **Target value**: For each query `[first, second]`, the target substring value is `first XOR second`
2. **Length limit**: Since values are ≤ 10^9 < 2^30, we only need substrings of length ≤ 30
3. **Shortest first**: We iterate by length (1 to 30), so the first entry in the map for each value is already the shortest substring
4. **Minimum left index**: For same length substrings, we iterate left to right, so the first occurrence has minimum left index
5. **Time complexity**: O(n × 30) for preprocessing + O(q) for queries

# Swift Translation

Here's the Python code translated to Swift:

```swift
import Foundation

// Generates all possible substrings of a given string
func allSubstrings(_ input: String) -> [String] {
    var substrings: [String] = []
    let chars = Array(input)  // Convert to array for index-based access
    let length = chars.count

    for i in 0..<length {
        for j in (i + 1)...length {
            let substring = String(chars[i..<j])
            substrings.append(substring)
        }
    }
    return substrings
}

// Finds the longest substring that appears in at least k strings
func longestSubstring(_ strings: [String], _ k: Int) -> String? {
    // Return nil if the array is empty
    guard !strings.isEmpty else { return nil }

    var longestStr = ""

    for s in strings {
        for substr in allSubstrings(s) {
            // Count how many strings contain this substring
            let count = strings.filter { $0.contains(substr) }.count

            // Update longest if this substring appears in >= k strings
            // and is longer than current longest
            if count >= k && substr.count > longestStr.count {
                longestStr = substr
            }
        }
    }

    // Return nil if no valid substring was found
    return longestStr.isEmpty ? nil : longestStr
}

// Example usage
let words = ["apple", "pineapple", "snapple"]
if let result = longestSubstring(words, 2) {
    print("Longest common substring: \(result)")
} else {
    print("No common substring found")
}
```

## How It Works

### `allSubstrings`
| Step | Description |
|------|-------------|
| Convert to Array | Swift Strings don't support integer indexing directly, so we convert to a `Character` array |
| Nested Loops | Outer loop sets the **start** index `i`, inner loop sets the **end** index `j` |
| Slice & Append | Each `chars[i..<j]` slice is converted back to a `String` and added to results |

### `longestSubstring`
| Step | Description |
|------|-------------|
| Guard Check | Uses `guard` (Swift's idiomatic way) instead of `if` to handle empty input |
| Double Loop | Iterates over each string, then each of its substrings |
| Filter & Count | Uses `.filter { $0.contains(substr) }.count` instead of Python's `sum()` |
| Track Longest | Updates `longestStr` when a longer valid substring is found |
| Return | Returns `nil` if no valid substring was found, otherwise returns the result |

### Key Swift Differences
- **No integer string indexing**: Swift requires converting strings to `Character` arrays
- **`guard` statement**: Cleaner early-return syntax compared to Python's `if`
- **`Optional<String>` = `String?`**: Swift's way of expressing nullable values
- **`.filter{}.count`**: Replaces Python's `sum(condition for item in list)` pattern

# Solution

## Approach
1. Numbers should come before letters in sorted results
2. Sort alphabetically (case-sensitive)
3. If same starting character → sort by length (descending)
4. If same starting character and length → sort by ASCII value (descending)
5. If same starting character, length, and ASCII value → maintain original order (stable sort)

## Implementation

```javascript
function sortBooks(books) {
  // Create array with original indices to maintain stable sort
  const indexedBooks = books.map((book, index) => ({ book, index }));

  indexedBooks.sort((a, b) => {
    const bookA = a.book;
    const bookB = b.book;

    const firstCharA = bookA[0];
    const firstCharB = bookB[0];

    // Get ASCII codes of first characters
    const asciiA = firstCharA.charCodeAt(0);
    const asciiB = firstCharB.charCodeAt(0);

    // Rule 1: Sort by first character (numbers before letters, case-sensitive)
    if (firstCharA !== firstCharB) {
      return asciiA - asciiB;
    }

    // Rule 2: If same starting character, sort by length (descending)
    if (bookA.length !== bookB.length) {
      return bookB.length - bookA.length;
    }

    // Rule 3: If same starting character and length, sort by ASCII value (descending)
    // Compare full string ASCII values
    for (let i = 0; i < bookA.length; i++) {
      const charCodeA = bookA.charCodeAt(i);
      const charCodeB = bookB.charCodeAt(i);

      if (charCodeA !== charCodeB) {
        return charCodeB - charCodeA; // Descending
      }
    }

    // Rule 4: If all same, maintain original order (stable sort)
    return a.index - b.index;
  });

  return indexedBooks.map(({ book }) => book);
}

// Test the function
const books = [
  "3 Little Pigs",
  "Alice in Wonderland",
  "1 Fish 2 Fish Red Fish Blue Fish",
  "1984",
  "Harry Potter and the Chamber of Secrets",
];

const sortedBooks = sortBooks(books);
console.log("Input:", books);
console.log("Output:", sortedBooks);
```

## Output

```
Input: [
  '3 Little Pigs',
  'Alice in Wonderland',
  '1 Fish 2 Fish Red Fish Blue Fish',
  '1984',
  'Harry Potter and the Chamber of Secrets'
]
Output: [
  '1 Fish 2 Fish Red Fish Blue Fish',
  '1984',
  'Alice in Wonderland',
  'Harry Potter and the Chamber of Secrets',
  '3 Little Pigs'
]
```

## Explanation

| Book | First Char | ASCII | Length |
|------|-----------|-------|--------|
| "1 Fish 2 Fish Red Fish Blue Fish" | '1' | 49 | 32 |
| "1984" | '1' | 49 | 4 |
| "Alice in Wonderland" | 'A' | 65 | 20 |
| "Harry Potter..." | 'H' | 72 | 39 |
| "3 Little Pigs" | '3' | 51 | 13 |

- **Step 1**: Numbers ('1', '3') come before letters ('A', 'H') → ASCII order: `1... < 3... < A... < H...`
- **Step 2**: Both "1 Fish..." and "1984" start with '1'; "1 Fish..." (length 32) > "1984" (length 4) → descending length puts "1 Fish..." first
- **Step 3**: "Alice..." and "Harry..." have different first characters, so they're sorted by ASCII value directly

# Random Number Generator in C++ (0-19)

## Solution

Here's a clean C++ program that generates a random number between 0 and 19 with even distribution:

```cpp
#include <iostream>
#include <random>

int main() {
    // Create a random device for seeding
    std::random_device rd;

    // Mersenne Twister engine seeded with random_device
    std::mt19937 gen(rd());

    // Uniform distribution between 0 and 19 (inclusive)
    std::uniform_int_distribution<int> dist(0, 19);

    // Generate and print a random number
    int randomNumber = dist(gen);
    std::cout << "Random number: " << randomNumber << std::endl;

    return 0;
}
```

---

## Example: Generate Multiple Numbers & Verify Distribution

```cpp
#include <iostream>
#include <random>
#include <map>
#include <iomanip>

int main() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<int> dist(0, 19);

    const int TOTAL_ROLLS = 100000;
    std::map<int, int> frequency;

    // Initialize all keys
    for (int i = 0; i <= 19; i++) {
        frequency[i] = 0;
    }

    // Generate random numbers
    for (int i = 0; i < TOTAL_ROLLS; i++) {
        frequency[dist(gen)]++;
    }

    // Display frequency table
    std::cout << "Distribution over " << TOTAL_ROLLS << " rolls:\n";
    std::cout << std::string(40, '-') << "\n";

    for (const auto& [num, count] : frequency) {
        double percentage = (count * 100.0) / TOTAL_ROLLS;
        std::cout << "Number " << std::setw(2) << num << ": "
                  << std::setw(6) << count << " times | "
                  << std::fixed << std::setprecision(2)
                  << percentage << "%\n";
    }

    return 0;
}
```

---

## Key Components Explained

| Component | Purpose |
|-----------|---------|
| `std::random_device` | Provides a non-deterministic seed |
| `std::mt19937` | Mersenne Twister - high quality PRNG |
| `std::uniform_int_distribution<int>(0, 19)` | Ensures **even distribution** across [0, 19] |

---

## Why NOT use `rand() % 20`?

```cpp
// ❌ BAD - Biased and low quality
int bad = rand() % 20;

// ✅ GOOD - Uniform and high quality
std::uniform_int_distribution<int> dist(0, 19);
int good = dist(gen);
```

**Problems with `rand() % 20`:**
- ❌ **Modulo bias** — uneven distribution if `RAND_MAX` isn't divisible by 20
- ❌ Poor randomness quality
- ❌ Not thread-safe

