## Implementation

### Database Configuration (config/database.js)
```javascript
const mongoose = require('mongoose');

const connectDB = async () => {
  try {
    const conn = await mongoose.connect(process.env.MONGODB_URI, {
      useNewUrlParser: true,
      useUnifiedTopology: true,
    });

    console.log(`✅ MongoDB Connected: ${conn.connection.host}`);

    // Handle connection events
    mongoose.connection.on('error', (err) => {
      console.error(`❌ MongoDB connection error: ${err}`);
    });

    mongoose.connection.on('disconnected', () => {
      console.warn('⚠️  MongoDB disconnected');
    });

  } catch (error) {
    console.error(`❌ Connection failed: ${error.message}`);
    process.exit(1);
  }
};

module.exports = connectDB;
```

### Post Model (models/Post.js)
```javascript
const mongoose = require('mongoose');

const postSchema = new mongoose.Schema(
  {
    title: {
      type: String,
      required: [true, 'Title is required'],
      trim: true,
      minlength: [3, 'Title must be at least 3 characters'],
      maxlength: [100, 'Title cannot exceed 100 characters'],
    },
    text: {
      type: String,
      required: [true, 'Text content is required'],
      trim: true,
      minlength: [10, 'Text must be at least 10 characters'],
    },
    author: {
      type: String,
      required: [true, 'Author is required'],
      trim: true,
      minlength: [2, 'Author name must be at least 2 characters'],
      maxlength: [50, 'Author name cannot exceed 50 characters'],
    },
    published: {
      type: Boolean,
      default: true,
    },
  },
  {
    timestamps: true, // Adds createdAt and updatedAt automatically
    versionKey: false,
  }
);

// Add index for faster queries
postSchema.index({ author: 1 });
postSchema.index({ createdAt: -1 });

// Custom method to format response
postSchema.methods.toJSON = function () {
  const post = this.toObject();
  post.id = post._id;
  delete post._id;
  return post;
};

module.exports = mongoose.model('Post', postSchema);
```

### Validation Middleware (middleware/validate.js)
```javascript
const validatePost = (req, res, next) => {
  const { title, text, author } = req.body;
  const errors = [];

  if (!title || typeof title !== 'string') {
    errors.push('Title is required and must be a string');
  }

  if (!text || typeof text !== 'string') {
    errors.push('Text is required and must be a string');
  }

  if (!author || typeof author !== 'string') {
    errors.push('Author is required and must be a string');
  }

  if (errors.length > 0) {
    return res.status(400).json({
      success: false,
      errors,
    });
  }

  next();
};

module.exports = { validatePost };
```

### Routes (routes/posts.js)
```javascript
const express = require('express');
const router = express.Router();
const Post = require('../models/Post');
const { validatePost } = require('../middleware/validate');

// ─── GET All Posts ───────────────────────────────────────────────────────────
router.get('/', async (req, res) => {
  try {
    const {
      page = 1,
      limit = 10,
      author,
      sort = '-createdAt', // Default: newest first
    } = req.query;

    // Build filter object
    const filter = {};
    if (author) {
      filter.author = { $regex: author, $options: 'i' }; // Case-insensitive search
    }

    const skip = (parseInt(page) - 1) * parseInt(limit);

    const [posts, total] = await Promise.all([
      Post.find(filter)
        .sort(sort)
        .skip(skip)
        .limit(parseInt(limit))
        .select('title text author createdAt'), // Select specific fields
      Post.countDocuments(filter),
    ]);

    res.status(200).json({
      success: true,
      data: {
        posts,
        pagination: {
          total,
          page: parseInt(page),
          limit: parseInt(limit),
          totalPages: Math.ceil(total / parseInt(limit)),
        },
      },
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      message: 'Failed to fetch posts',
      error: error.message,
    });
  }
});

// ─── GET Single Post ─────────────────────────────────────────────────────────
router.get('/:id', async (req, res) => {
  try {
    const post = await Post.findById(req.params.id);

    if (!post) {
      return res.status(404).json({
        success: false,
        message: 'Post not found',
      });
    }

    res.status(200).json({
      success: true,
      data: post,
    });
  } catch (error) {
    // Handle invalid MongoDB ID format
    if (error.name === 'CastError') {
      return res.status(400).json({
        success: false,
        message: 'Invalid post ID format',
      });
    }

    res.status(500).json({
      success: false,
      message: 'Failed to fetch post',
      error: error.message,
    });
  }
});

// ─── CREATE Post ─────────────────────────────────────────────────────────────
router.post('/', validatePost, async (req, res) => {
  try {
    const { title, text, author } = req.body;

    const post = await Post.create({ title, text, author });

    res.status(201).json({
      success: true,
      message: 'Post created successfully',
      data: post,
    });
  } catch (error) {
    if (error.name === 'ValidationError') {
      const messages = Object.values(error.errors).map((e) => e.message);
      return res.status(400).json({
        success: false,
        errors: messages,
      });
    }

    res.status(500).json({
      success: false,
      message: 'Failed to create post',
      error: error.message,
    });
  }
});

// ─── UPDATE Post ─────────────────────────────────────────────────────────────
router.put('/:id', validatePost, async (req, res) => {
  try {
    const { title, text, author } = req.body;

    const post = await Post.findByIdAndUpdate(
      req.params.id,
      { title, text, author },
      {
        new: true,        // Return updated document
        runValidators: true, // Run schema validators on update
      }
    );

    if (!post) {
      return res.status(404).json({
        success: false,
        message: 'Post not found',
      });
    }

    res.status(200).json({
      success: true,
      message: 'Post updated successfully',
      data: post,
    });
  } catch (error) {
    if (error.name === 'CastError') {
      return res.status(400).json({
        success: false,
        message: 'Invalid post ID format',
      });
    }

    res.status(500).json({
      success: false,
      message: 'Failed to update post',
      error: error.message,
    });
  }
});

// ─── DELETE Post ─────────────────────────────────────────────────────────────
router.delete('/:id', async (req, res) => {
  try {
    const post = await Post.findByIdAndDelete(req.params.id);

    if (!post) {
      return res.status(404).json({
        success: false,
        message: 'Post not found',
      });
    }

    res.status(200).json({
      success: true,
      message: 'Post deleted successfully',
      data: post,
    });
  } catch (error) {
    if (error.name === 'CastError') {
      return res.status(400).json({
        success: false,
        message: 'Invalid post ID format',
      });
    }

    res.status(500).json({
      success: false,
      message: 'Failed to delete post',
      error: error.message,
    });
  }
});

module.exports = router;
```

### Main Server (server.js)
```javascript
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const connectDB = require('./config/database');
const postRoutes = require('./routes/posts');

const app = express();
const PORT = process.env.PORT || 3000;

// ─── Connect to Database ──────────────────────────────────────────────────────
connectDB();

// ─── Middleware ───────────────────────────────────────────────────────────────
app.use(helmet());                          // Security headers
app.use(cors());                            // Enable CORS
app.use(morgan('dev'));                     // HTTP request logger
app.use(express.json());                   // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse URL-encoded bodies

// ─── Routes ───────────────────────────────────────────────────────────────────
app.use('/api/posts', postRoutes);

// ─── Health Check ─────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.status(200).json({
    success: true,
    message: 'Server is running',
    timestamp: new Date().toISOString(),
  });
});

// ─── 404 Handler ─────────────────────────────────────────────────────────────
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: `Route ${req.originalUrl} not found`,
  });
});

// ─── Global Error Handler ─────────────────────────────────────────────────────
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    success: false,
    message: 'Internal server error',
    error: process.env.NODE_ENV === 'development' ? err.message : undefined,
  });
});

// ─── Start Server ─────────────────────────────────────────────────────────────
app.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});
```

